<script setup>
import {ref} from 'vue'
import Icon from '../Icon.vue'
defineProps({profile:Object})
const copied=ref(false)
async function copy(id){try{await navigator.clipboard.writeText(id);copied.value=true;setTimeout(()=>copied.value=false,2000)}catch{copied.value=false}}
</script>
<template><section v-if="profile?.lms_id" class="lms-identity" aria-label="Your SISU digital ID card"><div class="identity-top"><strong>sisu<span>.</span></strong><span>DIGITAL LEARNING ID</span></div><div class="identity-main"><div class="identity-photo"><img v-if="profile.profile_image" :src="profile.profile_image" :alt="profile.display_name+' profile photo'"><Icon v-else :name="profile.kind==='Institute'?'Building2':'UserRound'" :size="36"/></div><div><span class="identity-role">{{profile.kind}}</span><h2>{{profile.display_name}}</h2><p v-if="profile.username">@{{profile.username}}</p><strong class="identity-number">{{profile.lms_id}}</strong></div></div><div class="identity-bottom"><span>One identity. Your learning journey.</span><button type="button" @click="copy(profile.lms_id)" :aria-label="'Copy LMS ID '+profile.lms_id"><Icon :name="copied?'Check':'Copy'" :size="14"/>{{copied?'Copied':'Copy ID'}}</button></div></section></template>
<style scoped>
